/// <summary>
///     The <c>AVASalesCopyingFrm_CustQuotationJourDS_Extension</c> class is the extension for <c>SalesCopying</c>
/// </summary>
[ExtensionOf(formDataSourceStr(SalesCopying, CustQuotationJour))]
final class AVASalesCopyingFrm_CustQuotationJourDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>init</c> method.
/// </summary>
void init()
{
    Query                   locQuery;
    QueryBuildDataSource    locQBDSBase;
    QueryBuildDataSource    locQBDS;
    QueryBuildRange         locQBR;

    next init();

    locQuery    = this.query();
    locQBDS     = this.queryBuildDataSource();
    locQbdsBase = locQuery.dataSourceTable(tableNum(CustQuotationJour));
    locQBDS     = locQbdsBase.addDataSource(tableNum(AVACustQuotationJourLatestJournalView), 'AVACustQuotationJourLatestJournalView');
    locQBDS.joinMode(JoinMode::ExistsJoin);
    locQBDS.addLink(fieldnum(CustQuotationJour, QuotationDate), 
                    fieldnum(AVACustQuotationJourLatestJournalView, QuotationDate), 
                    locQbdsBase.name()                                              );
    locQBDS.addLink(fieldnum(CustQuotationJour, QuotationId), 
                    fieldnum(AVACustQuotationJourLatestJournalView, QuotationId), 
                    locQbdsBase.name()                                              );
    locQBDS.relations(true);
}
